<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\SkillLogbookRequirement; use Illuminate\Http\JsonResponse;
class SkillLogbookRequirementController extends Controller { public function index(\Illuminate\Http\Request $request):JsonResponse{return ApiResponse::success(SkillLogbookRequirement::with(['course:id,code,name_ar,name_en','department:id,name_ar,name_en'])->when(!$request->boolean('show_archived'), fn($q)=>$q->whereNull('archived_at'))->orderBy('skill_code')->get());} public function store(\Illuminate\Http\Request $r):JsonResponse{$d=$r->validate(['skill_code'=>['required','string','unique:skill_logbook_requirements,skill_code'],'name_ar'=>['required','string'],'name_en'=>['nullable','string'],'course_id'=>['nullable','exists:courses,id'],'department_id'=>['nullable','exists:departments,id'],'required_proficiency'=>['nullable','string'],'minimum_count'=>['nullable','integer','min:0'],'requires_supervisor_signature'=>['boolean'],'notes'=>['nullable','string']]);return ApiResponse::success(SkillLogbookRequirement::create($d),'Skill requirement created.',[],201);} public function update(\Illuminate\Http\Request $r, SkillLogbookRequirement $skillLogbookRequirement):JsonResponse{$skillLogbookRequirement->update($r->validate(['skill_code'=>['sometimes','string'],'name_ar'=>['sometimes','string'],'name_en'=>['nullable','string'],'course_id'=>['nullable','exists:courses,id'],'department_id'=>['nullable','exists:departments,id'],'required_proficiency'=>['nullable','string'],'minimum_count'=>['nullable','integer','min:0'],'requires_supervisor_signature'=>['boolean'],'notes'=>['nullable','string']]));return ApiResponse::success($skillLogbookRequirement->fresh());} public function archive(SkillLogbookRequirement $skillLogbookRequirement):JsonResponse{$skillLogbookRequirement->update(['archived_at'=>now()]);return ApiResponse::success($skillLogbookRequirement->fresh(),'Record archived.');} }
